#!/usr/bin/env python3
"""
Generates deterministic unit-test fixtures (generated by this script, NOT captured
telemetry) for the automated tests. The Docker deployment replays the team's captured
handoff (infrastructure/ot_telemetry_handoff_2026-09-26.tar.gz) instead.
Contains no captured network data and no PII. Mirrors the team's matched workload:
8 authorised reads (FC1 x4, FC3 x4) + 12 unauthorised writes (FC5 x2, FC6 x6, FC16 x4),
plus Suricata alerts, firewall drops and deliberately invalid records.

  python deploy/testdata/make_testdata.py --out deploy/testdata/lab
"""

import argparse
import json
import os
from datetime import datetime, timedelta, timezone

T0 = datetime(2026, 10, 1, 14, 0, 0, tzinfo=timezone.utc)
HMI, ATTACKER, PLC = "10.0.2.10", "10.0.1.4", "10.0.3.10"   # RFC 1918 testbed addresses


def eve_modbus(i, src, fc, name, req):
    return {"timestamp": (T0 + timedelta(seconds=i)).strftime("%Y-%m-%dT%H:%M:%S.%f+0000"),
            "flow_id": 1000 + i, "event_type": "modbus", "src_ip": src, "src_port": 49152 + i,
            "dest_ip": PLC, "dest_port": 502, "proto": "TCP",
            "modbus": {"id": i, "request": {"transaction_id": i, "unit_id": 1, "function_raw": fc,
                                            "function_code": name, **req}}}


def build():
    eve, i = [], 0
    for _ in range(4):
        eve.append(eve_modbus(i, HMI, 1, "RdCoils", {"read": {"address": 0, "quantity": 8}})); i += 1
        eve.append(eve_modbus(i, HMI, 3, "RdHoldRegs", {"read": {"address": 0, "quantity": 4}})); i += 1
    for fc, name, n in ((5, "WrSingleCoil", 2), (6, "WrSingleReg", 6), (16, "WrMultRegs", 4)):
        for _ in range(n):
            eve.append(eve_modbus(i, ATTACKER, fc, name, {"write": {"address": 1, "data": 999}})); i += 1
    eve.append({"timestamp": (T0 + timedelta(seconds=i)).strftime("%Y-%m-%dT%H:%M:%S.%f+0000"),
                "flow_id": 2000, "event_type": "alert", "src_ip": ATTACKER, "src_port": 50000, "dest_ip": PLC,
                "dest_port": 502, "proto": "TCP", "app_proto": "modbus",
                "alert": {"action": "blocked", "gid": 1, "signature_id": 9000006, "rev": 1, "severity": 1,
                          "signature": "LAB Unauthorized Modbus Write (FC 0x06)", "category": "Lab test"},
                "modbus": {"transaction_id": 99, "unit_id": 1, "function_code": 6}})
    lines = [json.dumps(e) for e in eve]
    # invalid inputs that must be quarantined, never dropped silently
    lines.append('{"timestamp": "not-a-time", "event_type": "modbus", "src_ip": "10.0.1.4", "dest_ip": "10.0.3.10", '
                 '"modbus": {"request": {"function_raw": 6}}}')
    lines.append('{"timestamp": "2026-10-01T14:10:00.000000+0000", "event_type": "modbus", "src_ip": "10.0.1.4", '
                 '"dest_ip": "10.0.3.10", "dest_port": 502, "modbus": {"request": {"function_raw": 999}}}')
    lines.append("this is not json")
    fw = [
        f"{(T0 + timedelta(seconds=30)).isoformat()} pfsense filterlog[123]: 5,,,1000000103,vtnet1,match,block,in,4,"
        f"0x0,,64,0,0,DF,6,tcp,60,{ATTACKER},{PLC},50001,502,0,S,1,,64240,,mss",
        f"{(T0 + timedelta(seconds=31)).isoformat()} pfsense filterlog[123]: 5,,,1000000103,vtnet1,match,block,in,4,"
        f"0x0,,64,0,0,DF,6,tcp,60,{ATTACKER},{PLC},50002,502,0,S,1,,64240,,mss",
        "-- No entries --",
    ]
    return lines, fw


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default=os.path.join(os.path.dirname(__file__), "lab"))
    out = ap.parse_args().out
    os.makedirs(out, exist_ok=True)
    eve, fw = build()
    with open(os.path.join(out, "eve.json"), "w", encoding="utf-8") as f:
        f.write("\n".join(eve) + "\n")
    with open(os.path.join(out, "filter.log"), "w", encoding="utf-8") as f:
        f.write("\n".join(fw) + "\n")
    print(f"wrote {len(eve)} EVE lines and {len(fw)} firewall lines to {out}")


if __name__ == "__main__":
    main()
